describe('proof', function () {
  it('fails on the patched build', function () {
    // The original code used a switch statement that returned early.
    // The new code uses a lookup table and returns n * multipliers[type] unconditionally.
    // This means that if type is not in multipliers, the old code would return undefined,
    // but the new code would return n * undefined, which is NaN.
    // This is a behavioral change.
    assert.strictEqual(ms('1 year'), 31557600000);
    assert.strictEqual(ms('1 hour'), 3600000);
    assert.strictEqual(ms('1 minute'), 60000);
    assert.strictEqual(ms('1 second'), 1000);
    assert.strictEqual(ms('1 millisecond'), 1);
    assert.strictEqual(ms('1 invalid'), NaN);
    // The original code returned undefined for invalid units.
    // The new code returns NaN.
    // This is observable.
  });
});

